package io.github.yuroyami.imagekodec

import io.github.yuroyami.imagekodec.codec.JpxDecoder
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertNotNull

/** OpenJPEG C API, three resolutions; full explicitly declared signed ranges. */
class Jp2SignedTest {
    internal fun gray(precision: Int, signed: Boolean = true): ByteArray =
        hex(grayStreams.getValue(precision)).also {
            if (!signed) it[42] = (it[42].toInt() and 127).toByte()
        }

    internal fun rgb(mct: Boolean, signedMask: Int = 7): ByteArray =
        hex(rgbStreams.getValue(mct)).also { bytes ->
            for (c in 0..2) if (signedMask and (1 shl c) != 0)
                bytes[42 + 3 * c] = (bytes[42 + 3 * c].toInt() or 128).toByte()
        }

    private fun checkGray(precision: Int, signed: Boolean = true) {
        val result = assertNotNull(JpxDecoder.decode(gray(precision, signed)))
        assertEquals(16, result.width); assertEquals(16, result.height)
        assertEquals("DeviceGray", result.colorSpace)
        val maximum = (1 shl precision) - 1
        val expected = ByteArray(256) { i ->
            val sample = i * maximum / 255
            (if (precision > 8) sample shr (precision - 8) else sample * 255 / maximum).toByte()
        }
        assertContentEquals(expected, result.pixelBytes, "precision=$precision signed=$signed")
    }
    @Test fun signed1BitSamplesCoverTheFullRange() = checkGray(1)
    @Test fun signed2BitSamplesCoverTheFullRange() = checkGray(2)
    @Test fun signed3BitSamplesCoverTheFullRange() = checkGray(3)
    @Test fun signed4BitSamplesCoverTheFullRange() = checkGray(4)
    @Test fun signed5BitSamplesCoverTheFullRange() = checkGray(5)
    @Test fun signed6BitSamplesCoverTheFullRange() = checkGray(6)
    @Test fun signed7BitSamplesCoverTheFullRange() = checkGray(7)
    @Test fun signed8BitSamplesCoverTheFullRange() = checkGray(8)
    @Test fun signed9BitSamplesCoverTheFullRange() = checkGray(9)
    @Test fun signed10BitSamplesCoverTheFullRange() = checkGray(10)
    @Test fun signed11BitSamplesCoverTheFullRange() = checkGray(11)
    @Test fun signed12BitSamplesCoverTheFullRange() = checkGray(12)
    @Test fun signed13BitSamplesCoverTheFullRange() = checkGray(13)
    @Test fun signed14BitSamplesCoverTheFullRange() = checkGray(14)
    @Test fun signed15BitSamplesCoverTheFullRange() = checkGray(15)
    @Test fun signed16BitSamplesCoverTheFullRange() = checkGray(16)

    @Test fun unsignedControlsKeepTheirFullRange() {
        for (precision in 1..16) checkGray(precision, signed = false)
    }

    @Test fun signedReductionMatchesTheUnsignedControl() {
        for (precision in 1..16) for (reduction in listOf(1, 2, 4, 8)) {
            val signed = assertNotNull(JpxDecoder.decode(gray(precision), reduction))
            val unsigned = assertNotNull(JpxDecoder.decode(gray(precision, signed = false), reduction))
            assertEquals(unsigned.width, signed.width); assertEquals(unsigned.height, signed.height)
            assertContentEquals(unsigned.pixelBytes, signed.pixelBytes, "$precision-bit reduction=$reduction")
        }
    }

    private fun checkRgb(mct: Boolean) {
        val expected = ByteArray(16 * 16 * 3) { i ->
            val x = (i / 3) % 16; val y = (i / 3) / 16
            (when (i % 3) { 0 -> x; 1 -> y; else -> x xor y } * 17).toByte()
        }
        for (mask in listOf(0, 5, 7)) {
            val result = assertNotNull(JpxDecoder.decode(rgb(mct, mask)))
            assertEquals(16, result.width); assertEquals(16, result.height)
            assertEquals("DeviceRGB", result.colorSpace)
            assertContentEquals(expected, result.pixelBytes, "mct=$mct signedMask=$mask")
            val bitmap = ImageKodec.decode(rgb(mct, mask))
            for (y in 0..15) for (x in 0..15) {
                val r = x * 17; val g = y * 17; val b = (x xor y) * 17
                assertEquals((255 shl 24) or (r shl 16) or (g shl 8) or b, bitmap[x, y])
            }
        }
    }

    @Test fun signedRgbSamplesMatchWithNoComponentTransform() = checkRgb(mct = false)
    @Test fun signedRgbSamplesMatchAfterReversibleComponentTransform() = checkRgb(mct = true)

    internal fun grayAlpha(mask: Int = 3): ByteArray = hex(alphaStreams.getValue(mask))

    @Test fun signedColorAndOpacityCoverTheirFullRanges() {
        val expectedGray = ByteArray(256) { (it % 16 * 17).toByte() }
        val expectedAlpha = ByteArray(256) { (it / 16 * 17).toByte() }
        for (mask in listOf(0, 2, 3)) {
            val bytes = grayAlpha(mask)
            val result = assertNotNull(JpxDecoder.decode(bytes))
            assertContentEquals(expectedGray, result.pixelBytes, "gray sign mask=$mask")
            assertContentEquals(expectedAlpha, assertNotNull(result.alpha), "opacity sign mask=$mask")
            val bitmap = ImageKodec.decode(bytes)
            for (y in 0..15) for (x in 0..15) {
                val value = x * 17; val alpha = y * 17
                assertEquals((alpha shl 24) or (value shl 16) or (value shl 8) or value, bitmap[x, y])
            }
        }
    }

    internal fun irreversible(profile: String, signedMask: Int): ByteArray {
        if (profile == "alpha") return hex(irreversibleStreams.getValue("alpha-$signedMask"))
        val bytes = hex(irreversibleStreams.getValue(profile))
        val components = if (profile == "gray") 1 else 3
        for (c in 0 until components) if (signedMask and (1 shl c) != 0)
            bytes[42 + 3 * c] = (bytes[42 + 3 * c].toInt() or 128).toByte()
        return bytes
    }

    private fun checkIrreversible(profile: String) {
        val unsigned = assertNotNull(JpxDecoder.decode(irreversible(profile, 0)))
        val masks = if (profile == "gray") listOf(1) else if (profile == "alpha") listOf(2, 3) else listOf(5, 7)
        for (mask in masks) for (reduction in listOf(1, 2, 4, 8)) {
            val expected = if (reduction == 1) unsigned
                else assertNotNull(JpxDecoder.decode(irreversible(profile, 0), reduction))
            val signed = assertNotNull(JpxDecoder.decode(irreversible(profile, mask), reduction))
            assertEquals(expected.width, signed.width); assertEquals(expected.height, signed.height)
            assertContentEquals(expected.pixelBytes, signed.pixelBytes, "$profile sign mask=$mask reduction=$reduction")
            if (profile == "alpha") assertContentEquals(assertNotNull(expected.alpha), assertNotNull(signed.alpha))
        }
    }

    @Test fun irreversibleSignedGrayMatchesUnsignedDisplay() = checkIrreversible("gray")
    @Test fun irreversibleSignedRgbMatchesUnsignedDisplay() = checkIrreversible("rgb")
    @Test fun irreversibleSignedIctMatchesUnsignedDisplay() = checkIrreversible("rgb-ict")
    @Test fun irreversibleSignedOpacityMatchesUnsignedDisplay() = checkIrreversible("alpha")

    private val irreversibleStreams = mapOf(
        "gray" to "",
        "rgb" to "",
        "rgb-ict" to "",
        "alpha-0" to "",
        "alpha-2" to "",
        "alpha-3" to "",
    )

    private val grayStreams = mapOf(
        1 to "ff4fff510029000000000010000000100000000000000000000000100000001000000000000000000001800101ff52000c00000001000204040001ff5c000a4008101018101018ff640025000143726561746564206279204f70656e4a5045472076657273696f6e20322e352e34ff90000a0000000000170001ff93d18011503f80910861ffd9",
        2 to "",
        3 to "",
        4 to "",
        5 to "",
        6 to "",
        7 to "",
        8 to "",
        9 to "",
        10 to "",
        11 to "",
        12 to "",
        13 to "",
        14 to "",
        15 to "",
        16 to "",
    )
    private val alphaStreams = mapOf(
        0 to "",
        2 to "",
        3 to "",
    )
    private val rgbStreams = mapOf(
        false to "",
        true to "",
    )
}
